// Go caller for the omega-bridge native call ABI v1 test library.
// Run with Go 1.27.3 by tests/native/run.sh. Every Omega declaration comes from the omeganative
// package (omega_native.go, generated by tools/native); this file has no cgo of its own.
package main

import (
	"fmt"
	"os"
	"unsafe"

	on "omegacaller/omeganative"
)

var fails int

func check(name string, ok bool) {
	if ok {
		fmt.Println("PASS", name)
	} else {
		fmt.Println("FAIL", name)
		fails++
	}
}

func main() {
	const sentinel = uint64(6148914691236517205)
	var r uint64
	check("madd 3*5+7 = 22", on.Omega_madd(&r, 3, 5, 7) == 0 && r == 22)
	check("madd wraps = 3", on.Omega_madd(&r, ^uint64(0), 2, 5) == 0 && r == 3)
	check("madd large", on.Omega_madd(&r, 1311768467463790320, 18364758544493064720, 1085102592571150095) == 0 && r == 3637949782307626511)
	m3 := int64(-3)
	check("madd signed bits = -13", on.Omega_madd(&r, uint64(m3), 5, 2) == 0 && int64(r) == -13)
	r = sentinel
	check("smadd overflow traps 1, result unchanged", on.Omega_smadd(&r, 1<<62, 4, 0) == 1 && r == sentinel)
	var buf [4]uint64 // Go memory holding no Go pointers may be handed to C (cgo pointer rules)
	check("fill k=1 traps 3, result unchanged", on.Omega_fill(&r, unsafe.Pointer(&buf[0]), 4, 1) == 3 && r == sentinel)
	check("writes before the trap stay visible", buf[0] == 11 && buf[1] == 22 && buf[2] == 0)
	check("fill k=0 = 3", on.Omega_fill(&r, unsafe.Pointer(&buf[0]), 4, 0) == 0 && r == 3 && buf[2] == 33)
	check("null result refused 32", on.Omega_madd(nil, 3, 5, 7) == 32)
	// mix: six parameters (ulong, long, view uchar 3, edit uchar 2, view ulong 2, ulong), no result.
	// 5 + 20 + 7 = 32 (calc:08302bc4); 5 + 20 + 300 is 70 over 255 (calc:a6a8bb76), so the conversion traps 5.
	cb := [3]byte{1, 2, 3}
	var db [2]byte
	eb := [2]uint64{10, 20}
	r = sentinel
	check("mix six parameters, void result writes 0",
		on.Omega_mix(&r, 5, 1, unsafe.Pointer(&cb[0]), 3, unsafe.Pointer(&db[0]), 2, unsafe.Pointer(&eb[0]), 2, 7) == 0 && r == 0 && db == [2]byte{3, 32})
	db = [2]byte{}
	r = sentinel
	m1 := int64(-1)
	check("mix negative long traps 9 after both writes, result unchanged",
		on.Omega_mix(&r, 5, uint64(m1), unsafe.Pointer(&cb[0]), 3, unsafe.Pointer(&db[0]), 2, unsafe.Pointer(&eb[0]), 2, 7) == 9 && r == sentinel && db == [2]byte{3, 32})
	db = [2]byte{}
	check("mix uchar conversion 325 traps 5, first write visible",
		on.Omega_mix(&r, 5, 1, unsafe.Pointer(&cb[0]), 3, unsafe.Pointer(&db[0]), 2, unsafe.Pointer(&eb[0]), 2, 300) == 5 && r == sentinel && db == [2]byte{3, 0})
	if fails > 0 {
		fmt.Println("FAIL", fails, "failure(s)")
		os.Exit(1)
	}
	fmt.Println("PASS 0 failure(s)")
}
